# Python Error Handling Best Practices

## Overview
Effective error handling strategies for robust Python applications.

## Basic Try-Except

```python
try:
    result = risky_operation()
except Exception as e:
    print(f"Error occurred: {e}")
    result = None
```

## Specific Exception Handling

```python
import requests

def fetch_data(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.json()
    except requests.Timeout:
        print("Request timed out")
        return None
    except requests.ConnectionError:
        print("Connection failed")
        return None
    except requests.HTTPError as e:
        print(f"HTTP error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error: {e}")
        return None
```

## Try-Except-Else-Finally

```python
def process_file(filepath):
    file = None
    try:
        file = open(filepath, 'r')
        data = file.read()
    except FileNotFoundError:
        print(f"File not found: {filepath}")
        return None
    except PermissionError:
        print(f"Permission denied: {filepath}")
        return None
    else:
        # Runs if no exception occurred
        print("File read successfully")
        return data
    finally:
        # Always runs (cleanup)
        if file:
            file.close()
```

## Context Managers (Preferred)

```python
# Automatic resource cleanup
def process_file(filepath):
    try:
        with open(filepath, 'r') as file:
            return file.read()
    except FileNotFoundError:
        print(f"File not found: {filepath}")
        return None
```

## Handling Multiple Operations

```python
def process_chemicals(chemical_names):
    """Process list of chemicals with error handling."""
    results = []
    errors = []

    for name in chemical_names:
        try:
            result = process_chemical(name)
            results.append((name, result))
        except ValueError as e:
            errors.append((name, str(e)))
        except Exception as e:
            errors.append((name, f"Unexpected error: {e}"))

    if errors:
        print(f"Encountered {len(errors)} errors:")
        for name, error in errors:
            print(f"  {name}: {error}")

    return results, errors
```

## Custom Exceptions

```python
class ChemicalNotFoundError(Exception):
    """Raised when chemical cannot be found in database."""
    pass

class InvalidSmilesError(Exception):
    """Raised when SMILES string is invalid."""
    pass

def get_chemical_smiles(name):
    smiles = fetch_from_database(name)
    if smiles is None:
        raise ChemicalNotFoundError(f"Chemical '{name}' not found")
    if not validate_smiles(smiles):
        raise InvalidSmilesError(f"Invalid SMILES for '{name}': {smiles}")
    return smiles
```

## Retry Logic

```python
import time

def retry_operation(func, max_attempts=3, delay=1):
    """Retry an operation with exponential backoff."""
    for attempt in range(max_attempts):
        try:
            return func()
        except Exception as e:
            if attempt == max_attempts - 1:
                raise  # Re-raise on final attempt
            print(f"Attempt {attempt + 1} failed: {e}. Retrying...")
            time.sleep(delay * (2 ** attempt))

# Usage
result = retry_operation(lambda: fetch_from_api(url))
```

## Logging Errors

```python
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_with_logging(data):
    try:
        result = risky_operation(data)
        logger.info(f"Successfully processed: {data}")
        return result
    except ValueError as e:
        logger.error(f"Validation error for {data}: {e}")
        return None
    except Exception as e:
        logger.exception(f"Unexpected error processing {data}")
        return None
```

## Silent Failures vs Loud Failures

```python
# BAD: Silent failure
def bad_example(name):
    try:
        return process(name)
    except:
        return None  # User doesn't know what went wrong

# GOOD: Informative failure
def good_example(name):
    try:
        return process(name)
    except FileNotFoundError:
        print(f"Error: File not found for {name}")
        return None
    except ValueError as e:
        print(f"Error: Invalid value for {name}: {e}")
        return None

# BETTER: Let caller handle
def better_example(name):
    # Document exceptions in docstring
    # Let exceptions propagate
    return process(name)
```

## Validation with Exceptions

```python
def validate_input(value, min_val=0, max_val=100):
    """Validate input with informative errors."""
    if not isinstance(value, (int, float)):
        raise TypeError(f"Expected number, got {type(value).__name__}")
    if value < min_val or value > max_val:
        raise ValueError(f"Value {value} outside range [{min_val}, {max_val}]")
    return True
```

## Best Practices

1. **Catch specific exceptions**: Don't use bare `except:`
2. **Provide context**: Include helpful error messages
3. **Clean up resources**: Use context managers or finally
4. **Don't swallow exceptions**: Log or re-raise important errors
5. **Fail fast**: Validate inputs early
6. **Document exceptions**: List possible exceptions in docstrings

